<template>
 <div class="messages-page"><div class="messages-title"><div><span class="jade-eyebrow">关于家的事，慢慢聊</span><h1>我的消息</h1></div><RouterLink to="/houses">继续找房 ↗</RouterLink></div>
 <div class="inbox-layout"><aside class="conversation-list" aria-label="私人会话"><h2>私人聊天 <span>{{ conversations.length }}</span></h2><p class="list-note">只对你和对方可见</p><p v-if="listError" class="message-error" role="alert">{{ listError }} <button @click="refresh">重试</button></p><p v-else-if="loading" class="inbox-empty">正在加载会话…</p><p v-else-if="!conversations.length" class="inbox-empty">还没有聊天。<br>打开喜欢的房源，点击“私信房东”即可开始。</p><button v-for="c in conversations" :key="c.id" class="conversation-item" :class="{active:Number(c.id)===activeId}" @click="select(c.id)"><span class="person-mark">{{ c.otherName?.slice(0,1) || '房' }}</span><span class="conversation-copy"><strong>{{ c.otherName }} <small>{{ c.otherRole==='LANDLORD'?'房东':'用户' }}</small></strong><span>{{ c.houseTitle }}</span><small>{{ c.lastMessage || '还没有消息，打个招呼吧' }}</small></span><b v-if="c.unread" class="unread-dot">{{ c.unread>99?'99+':c.unread }}</b></button></aside>
 <section class="private-room" aria-label="聊天内容"><template v-if="active"><header class="room-heading"><div><h2>{{ active.otherName }}</h2><p>{{ active.city }} · {{ active.houseTitle }}</p></div><RouterLink :to="'/detail/'+active.houseId">查看房源 ↗</RouterLink></header><div ref="historyBox" class="private-history"><button v-if="hasOlder" class="older-button" :disabled="olderLoading" @click="older">{{ olderLoading?'加载中…':'查看更早消息' }}</button><p v-if="roomLoading" class="room-note">正在读取聊天记录…</p><p v-else-if="!messages.length" class="room-note">从一句问候开始，聊聊房子的细节。</p><article v-for="m in messages" :key="m.id" class="private-message" :class="{mine:Number(m.senderId)===user.userId}"><span class="message-avatar">{{ Number(m.senderId)===user.userId?'我':active.otherName?.slice(0,1) }}</span><div><div class="message-bubble">{{ m.content }}</div><small>{{ formatTime(m.createdAt) }}<span v-if="Number(m.senderId)===user.userId"> · {{ m.readAt?'已读':'已送达' }}</span></small></div></article></div><p v-if="roomError" class="message-error room-error" role="alert">{{ roomError }} <button @click="refresh">重新连接</button></p><div class="private-compose"><div class="compose-tools"><button type="button" :disabled="generating || sending" @click="aiOpen=!aiOpen">✦ 让小易帮我写</button><span>消息约每4秒更新</span></div><div v-if="aiOpen" class="ai-compose"><label for="ai-intent">告诉小易你想表达什么</label><div><input id="ai-intent" v-model="instruction" maxlength="1000" placeholder="例如：问问这套房是否还在，可以养猫吗？" :disabled="generating" @keydown.enter.prevent="generate" /><button :disabled="!instruction.trim() || generating" @click="generate">{{ generating?'小易正在拟写…':'生成待确认消息' }}</button></div><small>相关房源和最近聊天会提供给小易用于代拟；只有你点确认才发送。</small></div><MessageDraftCard v-for="d in drafts.filter(d=>Number(d.conversationId)===activeId)" :key="d.id" :draft="d" @sent="draftSent" @cancel="removeDraft" /><label class="compose-label" for="private-text">发送给 {{ active.otherName }}</label><textarea id="private-text" v-model="text" placeholder="问问房子的细节、入住时间，或约个方便的看房时间…" maxlength="2000" rows="3" :disabled="sending" @keydown.enter.exact="enterSend" /><div class="compose-bottom"><span>{{ text.length }}/2000 · Enter 发送，Shift+Enter 换行</span><button :disabled="!text.trim() || sending" @click="send">{{ sending?'发送中…':'发送消息 ↗' }}</button></div></div></template><div v-else class="no-conversation"><span class="letter-art" aria-hidden="true">✉</span><h2>让好房，从一段交流开始。</h2><p>从左侧选择会话，或去房源详情联系房东。<br>这里的私信会保留，方便你随时回来继续聊。</p><RouterLink to="/houses">去发现好房 →</RouterLink></div></section></div>
 </div>
</template>
<script setup>
import {requestId} from '../utils/requestId'
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useUserStore} from '../stores/user'
import {messagesApi} from '../api/messages'
import MessageDraftCard from '../components/MessageDraftCard.vue'
const user=useUserStore(),route=useRoute(),router=useRouter(),conversations=ref([]),messages=ref([]),drafts=ref([]),text=ref(''),instruction=ref(''),aiOpen=ref(false),generating=ref(false),sending=ref(false),loading=ref(true),roomLoading=ref(false),listError=ref(''),roomError=ref(''),historyBox=ref(null),hasOlder=ref(false),olderLoading=ref(false)
const activeId=computed(()=>Number(route.query.conversation)||0),active=computed(()=>conversations.value.find(c=>Number(c.id)===activeId.value))
let disposed=false,polling=false,version=0,timer,retryMessage=null
function formatTime(value){return new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
function select(id){router.replace({query:{conversation:id}})}
async function bottom(){await nextTick();const el=historyBox.value;if(el)el.scrollTop=el.scrollHeight}
async function refresh(){
 if(disposed||polling||document.hidden)return;polling=true
 const id=activeId.value,v=version
 try{const r=await messagesApi.inbox();if(disposed||v!==version)return;conversations.value=r.data||[];listError.value='';if(!id&&conversations.value.length){select(conversations.value[0].id);return}if(id&&active.value){const el=historyBox.value,nearBottom=!el||el.scrollHeight-el.scrollTop-el.clientHeight<100;const h=await messagesApi.history(id);if(disposed||v!==version||id!==activeId.value)return;if(!messages.value.length)hasOlder.value=(h.data||[]).length===100;const combined=new Map(messages.value.map(m=>[m.id,m]));for(const m of h.data||[])combined.set(m.id,m);messages.value=[...combined.values()].sort((a,b)=>a.id-b.id);roomError.value='';if(nearBottom)bottom();if(messages.value.length){await messagesApi.read(id,messages.value.at(-1).id);const c=conversations.value.find(c=>Number(c.id)===id);if(c)c.unread=0}}}
 catch(e){if(!disposed&&v===version){if(id)roomError.value=e.message||'连接暂时中断，稍后自动重试';else listError.value=e.message||'会话加载失败'}}finally{polling=false;loading.value=false;roomLoading.value=false}
}
watch(activeId,async()=>{version++;messages.value=[];text.value='';instruction.value='';aiOpen.value=false;roomError.value='';hasOlder.value=false;retryMessage=null;roomLoading.value=!!activeId.value;const id=activeId.value,v=version;try{if(id){const r=await messagesApi.history(id);if(disposed||v!==version)return;messages.value=r.data||[];hasOlder.value=messages.value.length===100;bottom()}}catch(e){if(v===version)roomError.value=e.message}finally{if(v===version)roomLoading.value=false}refresh()})
async function older(){if(olderLoading.value||!messages.value.length)return;olderLoading.value=true;const id=activeId.value,v=version,el=historyBox.value,height=el?.scrollHeight||0;try{const r=await messagesApi.history(id,{before:messages.value[0].id});if(v!==version||disposed)return;messages.value=[...(r.data||[]),...messages.value];hasOlder.value=r.data.length===100;await nextTick();if(el)el.scrollTop=el.scrollHeight-height}catch(e){roomError.value=e.message}finally{olderLoading.value=false}}
function enterSend(event){if(event.isComposing||event.keyCode===229)return;event.preventDefault();send()}
async function send(){if(sending.value||!text.value.trim()||!active.value)return;const content=text.value.trim(),id=activeId.value;if(!retryMessage||retryMessage.content!==content||retryMessage.id!==id)retryMessage={id,content,key:requestId()};sending.value=true;roomError.value='';try{await messagesApi.send(id,content,retryMessage.key);if(id===activeId.value)text.value='';retryMessage=null;await refresh();bottom()}catch(e){roomError.value=e.message||'发送失败，请重试'}finally{sending.value=false}}
async function generate(){if(generating.value||!instruction.value.trim()||!active.value)return;const id=activeId.value;generating.value=true;roomError.value='';try{const r=await messagesApi.draft(id,instruction.value);if(disposed)return;drafts.value.unshift(r.data);if(id===activeId.value){instruction.value='';aiOpen.value=false}}catch(e){roomError.value=e.message||'代拟失败，可直接输入消息'}finally{generating.value=false}}
function removeDraft(id){drafts.value=drafts.value.filter(d=>d.id!==id)}
async function draftSent(){await refresh();bottom()}
function visibility(){if(!document.hidden)refresh()}
onMounted(async()=>{await refresh();try{const r=await messagesApi.pending();if(!disposed)drafts.value=r.data||[]}catch{}timer=setInterval(refresh,4000);document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{disposed=true;version++;clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
